  "a_sentences": [
    {
      "a_text": "Nach Art. 831 ZGB ist eine Kündigung der Forderung gegenüber dem nichtschuldnerischen Dritteigentümer nur wirksam, wenn sie auch gegenüber dem Schuldner und dem Eigentümer erfolgt.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Die Kündigung muss auch dem Dritteigentümer zur Kenntnis gebracht werden, damit dieser die Zwangsvollstreckung abwenden kann, indem er die Schuld tilgt und das Pfand ablöst.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Art. 153 SchKG gewährt dem Dritteigentümer das Recht, Rechtsvorschlag zu erheben, um die Zwangsverwertung des Pfands zu verhindern, solange die Forderung nicht fällig ist.",
      "b_propositions": ["P3", "P6"]
    },
    {
      "a_text": "Die Fälligkeit der Forderung tritt erst durch eine Kündigung gegenüber dem Schuldner ein.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Wird die Betreibung vor Fälligkeit der Forderung gegenüber dem Dritteigentümer eingeleitet, kann der Rechtsvorschlag nicht beseitigt werden und die Pfandverwertung bleibt ausgeschlossen.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Selbst wenn der Schuldner die Kündigung später zur Kenntnis genommen haben sollte, bleibt die verfrüht eingeleitete Betreibung gegen den Willen des Dritteigentümers wirkungslos.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Das Bundesgericht bestätigt, dass die Beschwerde im Ergebnis unbegründet ist.",
      "b_propositions": ["P8"]
    }
  ]
}
